/* @lc app=leetcode id=3691 lang=kotlin */ class Solution { fun sp(a: IntArray, mx: Boolean): List<IntArray> = generateSequence(a to 0) { (arr, k) -> (1 shl (k + 1)).takeIf { it <= a.size }?.let { len -> IntArray(a.size - len + 1) { i -> if (mx) maxOf(arr[i], arr[i + (1 shl k)]) else minOf(arr[i], arr[i + (1 shl k)]) } to k + 1 } }.map { it.first }.toList() fun rg(smx: List<IntArray>, smn: List<IntArray>, l: Int, r: Int): Int = (31 - Integer.numberOfLeadingZeros(r - l + 1)).let { kk -> maxOf(smx[kk][l], smx[kk][r - (1 shl kk) + 1]) - minOf(smn[kk][l], smn[kk][r - (1 shl kk) + 1]) } fun maxTotalValue(nums: IntArray, k: Int): Long = sp(nums, true).let { smx -> sp(nums, false).let { smn -> java.util.PriorityQueue<LongArray>(compareByDescending<LongArray> { it[0] }).also { pq -> nums.indices.forEach { l -> pq.add(longArrayOf(rg(smx, smn, l, nums.size - 1).toLong(), l.toLong(), (nums.size - 1).toLong())) } }.let { pq -> generateSequence { pq.poll() }.take(k).sumOf { e -> (if (e[2] > e[1]) pq.add(longArrayOf(rg(smx, smn, e[1].toInt(), e[2].toInt() - 1).toLong(), e[1], e[2] - 1)) else false).let { e[0] } } } } } }